package cl.duoc.tienda.resena.model;
import jakarta.persistence.*;
@Entity @Table(name="resenas") public class Resena { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long usuarioId; private Long productoId; private Integer calificacion; private String comentario; public Resena(){} public Resena(Long usuarioId, Long productoId, Integer calificacion, String comentario){this.usuarioId=usuarioId; this.productoId=productoId; this.calificacion=calificacion; this.comentario=comentario;} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getUsuarioId(){return usuarioId;} public void setUsuarioId(Long v){usuarioId=v;} public Long getProductoId(){return productoId;} public void setProductoId(Long v){productoId=v;} public Integer getCalificacion(){return calificacion;} public void setCalificacion(Integer v){calificacion=v;} public String getComentario(){return comentario;} public void setComentario(String v){comentario=v;} }
